1	/**
2	 * Счёт.
3	 *
4	 * Сборка итогового документа из позиций. Порядок слагаемых значим и закреплён: подытог по
5	 * позициям, дальше — налоги и сборы, каждый отдельным полем, и только потом итог. Любое
6	 * новое слагаемое встаёт в этот порядок явно, а не «где получилось».
7	 */
8	
9	import type { BillingConfig } from './config.ts';
10	import { resolveConfig } from './config.ts';
11	import type { Customer } from './customer.ts';
12	import type { Kopeck } from './money.ts';
13	import { subtotal } from './lines.ts';
14	import type { Line } from './lines.ts';
15	
16	/** Выставленный счёт — так его показывают покупателю и так же проверяют в поддержке. */
17	export interface Invoice {
18	  /** Номер счёта, присваивает вызывающий. */
19	  number: string;
20	  customer: Customer;
21	  lines: readonly Line[];
22	  /** Подытог по позициям, до налогов. */
23	  subtotal: Kopeck;
24	  /** Сумма к оплате. Сейчас совпадает с подытогом: налогов в расчёте пока нет. */
25	  total: Kopeck;
26	}
27	
28	/** Собрать счёт из позиций. */
29	export function buildInvoice(
30	  number: string,
31	  customer: Customer,
32	  lines: readonly Line[],
33	  config?: Partial<BillingConfig>,
34	): Invoice {
35	  resolveConfig(config); // конфиг читается здесь одним местом — переопределения действуют везде
36	  const sub = subtotal(lines);
37	  return { number, customer, lines, subtotal: sub, total: sub };
38	}
