1	/**
2	 * Валидация покупателя на момент выставления счёта.
3	 *
4	 * Счёт выставляется на данные формы заказа как есть; опечатка в email или телефоне
5	 * узнаётся о себе только когда счёт не оплачен. Поэтому данные проверяются здесь,
6	 * на выставлении, а не в форме (форма не знает правил биллинга).
7	 *
8	 * Функция чистая: ничего не пишет и ничего не меняет — возвращает список кодов
9	 * нарушений. Пустой список — покупатель валиден. Коды и их порядок фиксированы:
10	 * сначала 'email', затем 'phone'.
11	 */
12	
13	import type { Customer } from './customer.ts';
14	
15	/** Проверить email: ровно одна '@', локальная часть непустая, домен содержит точку
16	 *  и не начинается и не заканчивается на неё, пробелов нигде нет. */
17	function emailViolations(email: string): boolean {
18	  if (email.includes(' ')) return true;
19	  const atCount = email.split('@').length - 1;
20	  if (atCount !== 1) return true;
21	  const [local, domain] = email.split('@');
22	  if (local.length === 0) return true;
23	  if (!domain.includes('.')) return true;
24	  if (domain.startsWith('.') || domain.endsWith('.')) return true;
25	  return false;
26	}
27	
28	/** Проверить телефон: либо '+7' и ровно 10 цифр после, либо '8' и ровно 10 цифр после.
29	 *  Никаких других символов (пробелов, скобок, дефисов) не допускаем — форма их не ставит. */
30	function phoneViolations(phone: string): boolean {
31	  return /^\+7\d{10}$/.test(phone) || /^8\d{10}$/.test(phone) ? false : true;
32	}
33	
34	/**
35	 * Валидировать покупателя.
36	 *
37	 * @returns список кодов нарушений в фиксированном порядке: сначала 'email', затем 'phone'.
38	 *          Пустой список — покупатель валиден.
39	 */
40	export function validateCustomer(customer: Customer): string[] {
41	  const violations: string[] = [];
42	  if (emailViolations(customer.email)) violations.push('email');
43	  if (phoneViolations(customer.phone)) violations.push('phone');
44	  return violations;
45	}
